// Generates the two Starlight entry files from the readable sources in src/:
//   frontend/index.tsx   <- src/frontend.js (+ src/dock.js inlined at the `/* @shared:dock */` marker)
//   webview/preload.ts   <- src/webview.js  (+ src/dock.js inlined)
// Run `node scripts/generate.mjs` after editing anything in src/. `--check` only reports whether the files are in sync.
// The generated files are committed, so the Starlight build (`bun run build`) needs nothing but bun.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const read = f => readFileSync(join(root, f), 'utf8');
const dock = read('src/dock.js');
const inlineDock = src => {
  if (!src.includes('/* @shared:dock */')) throw new Error('dock marker missing');
  return src.replace('/* @shared:dock */', () => dock);
};

const banner = from =>
  `// @ts-nocheck\n// GENERATED by scripts/generate.mjs from ${from}. Edit the files in src/ and run \`node scripts/generate.mjs\`, not this file.\n`;

export const frontend =
  banner('src/frontend.js and src/dock.js') +
  `import { definePlugin } from 'millennium';\n\n` +
  `const React = window.SP_REACT;\nconst API = window.MILLENNIUM_API;\n\n` +
  inlineDock(read('src/frontend.js')) +
  `\nexport default definePlugin(() => {\n  setup();\n  return panel();\n});\n`;

export const webview =
  banner('src/webview.js and src/dock.js') +
  `export default async function main() {\n` + inlineDock(read('src/webview.js')) + `}\n`;

const files = { 'frontend/index.tsx': frontend, 'webview/preload.ts': webview };
const check = process.argv.includes('--check');
let stale = false;
for (const [path, text] of Object.entries(files)) {
  const full = join(root, path);
  if (check) {
    let current = '';
    try { current = readFileSync(full, 'utf8'); } catch (e) { /* missing */ }
    if (current !== text) { console.log(`out of date: ${path}`); stale = true; } else console.log(`in sync: ${path}`);
  } else {
    mkdirSync(dirname(full), { recursive: true });
    writeFileSync(full, text);
    console.log(`wrote ${path} (${text.length} bytes)`);
  }
}
if (check && stale) process.exit(1);
